Caching:
// Cache-aside pattern with Node.js
const cache = async (key, ttl, fetchFn) => {
  const cached = await redis.get(key);
  if (cached) return JSON.parse(cached);

  const data = await fetchFn();
  await redis.setex(key, ttl, JSON.stringify(data));
  return data;
};

// Usage
app.get('/api/products', async (req, res) => {
  const products = await cache('products:all', 300, () =>
    Product.find({ active: true }).lean()
  );
  res.json(products);
});

// Invalidate on update
app.post('/api/products', async (req, res) => {
  await Product.create(req.body);
  await redis.del('products:all');  // Invalidate cache
  res.status(201).end();
});

Rate Limiting:
// Sliding window rate limiter
const rateLimit = async (ip, limit = 100, window = 60) => {
  const key = `ratelimit:${ip}:${Math.floor(Date.now() / 1000 / window)}`;
  const count = await redis.incr(key);
  if (count === 1) await redis.expire(key, window);

  return count <= limit;
};

// Express middleware
app.use(async (req, res, next) => {
  const allowed = await rateLimit(req.ip, 100, 60);
  if (!allowed) {
    return res.status(429).json({ error: 'Too many requests' });
  }
  next();
});

// More precise: sliding window with sorted sets
const preciseRateLimit = async (userId, maxRequests, windowMs) => {
  const now = Date.now();
  const key = `ratelimit:precise:${userId}`;

  await redis.zadd(key, now, `${now}`);
  await redis.zremrangebyscore(key, 0, now - windowMs);

  const count = await redis.zcard(key);
  await redis.expire(key, Math.ceil(windowMs / 1000));

  return count <= maxRequests;
};

