// Simple queue using Redis Lists
const addToQueue = async (queue, job) => {
  await redis.lpush(queue, JSON.stringify(job));
};

const processQueue = async (queue) => {
  while (true) {
    const result = await redis.brpop(queue, 0);
    const job = JSON.parse(result[1]);
    try {
      console.log('Processing:', job);
      await handleJob(job);
      console.log('Completed:', job.id);
    } catch (err) {
      console.error('Failed:', job.id, err.message);
      // Re-queue to dead letter queue
      await redis.lpush(`${queue}:failed`, JSON.stringify({ ...job, error: err.message }));
    }
  }
};

